import type { RuntimeGameState } from '../types/game';
import type { PersistedGameSession } from '../types/storage';
import { clearSupabaseGameSession, saveSupabaseGameSession } from './supabaseProgress';

export const GAME_SESSION_STORAGE_KEY = 'cuki_sriwijaya_state_v1';
export const CORRUPT_STORAGE_BACKUP_KEY = 'cuki_sriwijaya_corrupt_bak';
// Capture legality changed: never restore opportunities generated by the previous rules.
export const STORAGE_SCHEMA_VERSION = '1.3.0';

export interface StorageAdapter {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

/** Serializes only the authoritative runtime match snapshot to the architecture-approved key. */
export function saveGameSession(gameState: RuntimeGameState, storage: StorageAdapter | null = browserStorage()): boolean {
  if (!storage) {
    return false;
  }

  try {
    const session: PersistedGameSession = {
      version: STORAGE_SCHEMA_VERSION,
      lastSavedAt: new Date().toISOString(),
      gameState,
    };
    storage.setItem(GAME_SESSION_STORAGE_KEY, JSON.stringify(session));
    void saveSupabaseGameSession(gameState).catch(() => {
      // Cloud saves are best-effort; local saves keep the game playable.
    });
    return true;
  } catch {
    return false;
  }
}

/** Restores a structurally valid canonical snapshot, or resets safely after a storage fault. */
export function loadGameSession(storage: StorageAdapter | null = browserStorage()): RuntimeGameState | null {
  if (!storage) {
    return null;
  }

  let serialized: string | null;
  try {
    serialized = storage.getItem(GAME_SESSION_STORAGE_KEY);
  } catch {
    return null;
  }
  if (serialized === null) {
    return null;
  }

  try {
    const parsed: unknown = JSON.parse(serialized);
    if (!isPersistedGameSession(parsed)) {
      throw new Error('Invalid saved game schema');
    }
    return parsed.gameState;
  } catch {
    safelyDiscardCorruptSnapshot(storage, serialized);
    return null;
  }
}

/** Removes a saved match, for example when the user starts a fresh match after completion. */
export function clearGameSession(storage: StorageAdapter | null = browserStorage()): void {
  if (!storage) {
    return;
  }
  try {
    storage.removeItem(GAME_SESSION_STORAGE_KEY);
    void clearSupabaseGameSession().catch(() => {
      // Resetting local state should not depend on network availability.
    });
  } catch {
    // Browser storage can be unavailable or disabled; no gameplay state is affected.
  }
}

function browserStorage(): StorageAdapter | null {
  if (typeof window === 'undefined') {
    return null;
  }
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

function safelyDiscardCorruptSnapshot(storage: StorageAdapter, serialized: string): void {
  try {
    storage.setItem(CORRUPT_STORAGE_BACKUP_KEY, serialized);
    storage.removeItem(GAME_SESSION_STORAGE_KEY);
  } catch {
    // The required fallback is a clean in-memory IDLE state even if storage itself fails.
  }
}

function isPersistedGameSession(value: unknown): value is PersistedGameSession {
  if (!isRecord(value) || value.version !== STORAGE_SCHEMA_VERSION || typeof value.lastSavedAt !== 'string') {
    return false;
  }
  return isRuntimeGameState(value.gameState);
}

function isRuntimeGameState(value: unknown): value is RuntimeGameState {
  if (!isRecord(value)) {
    return false;
  }
  return (
    (value.gameMode === 'VS_AI' || value.gameMode === 'LOCAL_MULTIPLAYER') &&
    (value.playerCount === 2 || value.playerCount === 3 || value.playerCount === 4) &&
    isBoard(value.board) &&
    Array.isArray(value.players) &&
    value.players.length === value.playerCount &&
    value.players.every(isPlayer) &&
    isNonNegativeInteger(value.activePlayerIndex) &&
    value.activePlayerIndex < value.players.length &&
    isNonNegativeInteger(value.remainingOncak) &&
    isTurnState(value.turn) &&
    Array.isArray(value.legalOpportunities) &&
    (value.selectedCaptureGroup === null || isRecord(value.selectedCaptureGroup)) &&
    (value.matchStatus === 'IDLE' || value.matchStatus === 'INITIALIZING' || value.matchStatus === 'ACTIVE' || value.matchStatus === 'MATCH_FINISHED') &&
    isMatchResult(value.result)
  );
}

function isBoard(value: unknown): boolean {
  return Array.isArray(value) && value.length === 11 && value.every((row) =>
    Array.isArray(row) && row.length === 11 && row.every((intersection) =>
      isRecord(intersection) &&
      isCoordinate(intersection.coordinate) &&
      (intersection.kind === 'EMPTY' || intersection.kind === 'ONCAK' || intersection.kind === 'PAWN' || intersection.kind === 'CENTRAL_LOGO'),
    ),
  );
}

function isPlayer(value: unknown): boolean {
  return isRecord(value) && typeof value.id === 'string' && typeof value.name === 'string' &&
    (value.controllerType === 'HUMAN' || value.controllerType === 'AI') && isNonNegativeInteger(value.score) &&
    isRecord(value.pawn) && typeof value.pawn.id === 'string' && typeof value.pawn.playerId === 'string' && isPawnState(value.pawn.state);
}

function isPawnState(value: unknown): boolean {
  return isRecord(value) && (
    (value.status === 'OFF_BOARD' && value.position === null) ||
    (value.status === 'ON_BOARD' && isCoordinate(value.position))
  );
}

function isTurnState(value: unknown): boolean {
  return isRecord(value) &&
    typeof value.mandatorySameDiceCaptureRequired === 'boolean' &&
    typeof value.rerollRequired === 'boolean' &&
    (value.currentDiceValue === null || isDiceValue(value.currentDiceValue)) &&
    typeof value.phase === 'string';
}

function isMatchResult(value: unknown): boolean {
  return value === null || (isRecord(value) && (
    (value.kind === 'WINNER' && typeof value.winnerId === 'string') ||
    (value.kind === 'DRAW' && Array.isArray(value.tiedPlayerIds) && value.tiedPlayerIds.every((id) => typeof id === 'string'))
  ));
}

function isCoordinate(value: unknown): boolean {
  return isRecord(value) && isAxis(value.x) && isAxis(value.y);
}

function isAxis(value: unknown): boolean {
  return typeof value === 'number' && Number.isInteger(value) && value >= 0 && value <= 10;
}

function isDiceValue(value: unknown): boolean {
  return value === 1 || value === 2 || value === 3 || value === 4 || value === 5 || value === 6;
}

function isNonNegativeInteger(value: unknown): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value >= 0;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}
